<h2>Plan timelapse frames and storage</h2><p class="lead">Estimate frame count, card/storage use and final clip duration from interval capture settings.</p><div class="notice">Average frame size varies with RAW/JPEG compression and scene detail. Treat the storage result as an estimate and leave card/headroom for filesystem overhead and bursts.</div><div class="form-grid"><div class="field"><label for="hours">Capture duration (hours)</label><input id="hours" type="number" value="4" min="0.001" step="any"></div><div class="field"><label for="interval">Interval between frames (seconds)</label><input id="interval" type="number" value="5" min="0.001" step="any"></div><div class="field"><label for="size">Average file size per frame (MB)</label><input id="size" type="number" value="25" min="0" step="any"></div><div class="field"><label for="fps">Final video frame rate (fps)</label><input id="fps" type="number" value="24" min="0.001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Frames captured</span><strong id="frames">—</strong></div><div class="metric"><span>Estimated storage</span><strong id="storage">—</strong></div><div class="metric"><span>Final clip duration</span><strong id="clip">—</strong></div><div class="metric"><span>Real-time compression</span><strong id="ratio">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('frames').textContent='—';$('storage').textContent='—';$('clip').textContent='—';$('ratio').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const hrs=num('hours'),iv=num('interval'),sz=num('size'),fps=num('fps');if(!(hrs>0&&iv>0&&sz>=0&&fps>0))throw 0;const sec=hrs*3600,frames=Math.floor(sec/iv)+1,mb=frames*sz,clip=frames/fps,ratio=sec/clip;$('frames').textContent=fmt(frames,0);$('storage').textContent=mb>=1024?fmt(mb/1024,2)+' GB':fmt(mb,0)+' MB';$('clip').textContent=fmt(clip,2)+' s';$('ratio').textContent=fmt(ratio,1)+'×';$('note').textContent='Frame count includes the starting frame. Real cameras may create extra preview, sidecar or metadata files, so leave storage headroom.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
